public class User : BaseEntity
{
    public string Username { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string PasswordHash { get; set; } = string.Empty;  // OAuth kullanıcıları için nullable yapılabilir
    public string FirstName { get; set; } = string.Empty;
    public string LastName { get; set; } = string.Empty;
    public UserRole Role { get; set; }
    public bool IsActive { get; set; } = true;
    public Guid? BranchId { get; set; }
    public Branch? Branch { get; set; }

    // YENİ FIELD'LAR
    public string? OAuthProvider { get; set; }  // "AzureAD", "Google", null (local)
    public string? ExternalId { get; set; }     // Provider'daki unique ID (sub claim)

    // Navigation properties
    public ICollection<Assignment> Assignments { get; set; } = new List<Assignment>();
    public ICollection<Evaluation> Evaluations { get; set; } = new List<Evaluation>();
}

using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.Authentication.OpenIdConnect;
using Microsoft.Identity.Web;

var builder = WebApplication.CreateBuilder(args);

// Mevcut JWT Authentication (korunur)
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options =>
    {
        options.TokenValidationParameters = new TokenValidationParameters
        {
            ValidateIssuer = true,
            ValidateAudience = true,
            ValidateLifetime = true,
            ValidateIssuerSigningKey = true,
            ValidIssuer = builder.Configuration["Jwt:Issuer"],
            ValidAudience = builder.Configuration["Jwt:Audience"],
            IssuerSigningKey = new SymmetricSecurityKey(
                Encoding.UTF8.GetBytes(builder.Configuration["Jwt:Key"] ?? ""))
        };
    });

// YENİ: Azure AD Authentication
builder.Services.AddMicrosoftIdentityWebAppAuthentication(
    builder.Configuration,
    "AzureAd",
    OpenIdConnectDefaults.AuthenticationScheme,
    cookieScheme: null);

// YENİ: Google Authentication
builder.Services.AddAuthentication()
    .AddGoogle(options =>
    {
        options.ClientId = builder.Configuration["Google:ClientId"] ?? "";
        options.ClientSecret = builder.Configuration["Google:ClientSecret"] ?? "";
        options.CallbackPath = "/signin-google";

        // Claim mapping
        options.Scope.Add("profile");
        options.Scope.Add("email");
    });

var app = builder.Build();

app.UseAuthentication();
app.UseAuthorization();

using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Google;
using Microsoft.AspNetCore.Authentication.OpenIdConnect;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SecretCustomer.Core.Interfaces.Services;
using System.Security.Claims;

namespace SecretCustomer.API.Controllers.Api;

[ApiController]
[Route("api/oauth")]
public class OAuthController : ControllerBase
{
    private readonly IUserService _userService;
    private readonly IAuthService _authService;

    public OAuthController(IUserService userService, IAuthService authService)
    {
        _userService = userService;
        _authService = authService;
    }

    [HttpGet("login/azuread")]
    public IActionResult LoginAzureAd(string returnUrl = "/")
    {
        var properties = new AuthenticationProperties
        {
            RedirectUri = Url.Action(nameof(AzureAdCallback), new { returnUrl })
        };
        return Challenge(properties, OpenIdConnectDefaults.AuthenticationScheme);
    }

    [HttpGet("callback/azuread")]
    public async Task<IActionResult> AzureAdCallback(string returnUrl = "/")
    {
        var result = await HttpContext.AuthenticateAsync(OpenIdConnectDefaults.AuthenticationScheme);

        if (!result.Succeeded)
            return Unauthorized();

        var email = result.Principal?.FindFirstValue(ClaimTypes.Email);
        var name = result.Principal?.FindFirstValue(ClaimTypes.Name);
        var externalId = result.Principal?.FindFirstValue("sub");

        if (string.IsNullOrEmpty(email) || string.IsNullOrEmpty(externalId))
            return BadRequest("Invalid claims from provider");

        // Kullanıcı varsa getir, yoksa oluştur
        var user = await _userService.GetOrCreateOAuthUserAsync(
            email: email,
            firstName: name?.Split(' ')[0] ?? "User",
            lastName: name?.Split(' ').Skip(1).FirstOrDefault() ?? "",
            provider: "AzureAD",
            externalId: externalId
        );

        // JWT token oluştur
        var token = _authService.GenerateJwtToken(user);

        // Frontend'e redirect (token query string ile)
        return Redirect($"{returnUrl}?token={token}");
    }

    [HttpGet("login/google")]
    public IActionResult LoginGoogle(string returnUrl = "/")
    {
        var properties = new AuthenticationProperties
        {
            RedirectUri = Url.Action(nameof(GoogleCallback), new { returnUrl })
        };
        return Challenge(properties, GoogleDefaults.AuthenticationScheme);
    }

    [HttpGet("callback/google")]
    public async Task<IActionResult> GoogleCallback(string returnUrl = "/")
    {
        var result = await HttpContext.AuthenticateAsync(GoogleDefaults.AuthenticationScheme);

        if (!result.Succeeded)
            return Unauthorized();

        var email = result.Principal?.FindFirstValue(ClaimTypes.Email);
        var givenName = result.Principal?.FindFirstValue(ClaimTypes.GivenName);
        var surname = result.Principal?.FindFirstValue(ClaimTypes.Surname);
        var externalId = result.Principal?.FindFirstValue(ClaimTypes.NameIdentifier);

        if (string.IsNullOrEmpty(email) || string.IsNullOrEmpty(externalId))
            return BadRequest("Invalid claims from provider");

        var user = await _userService.GetOrCreateOAuthUserAsync(
            email: email,
            firstName: givenName ?? "User",
            lastName: surname ?? "",
            provider: "Google",
            externalId: externalId
        );

        var token = _authService.GenerateJwtToken(user);
        return Redirect($"{returnUrl}?token={token}");
    }
}

public async Task<User> GetOrCreateOAuthUserAsync(
    string email,
    string firstName,
    string lastName,
    string provider,
    string externalId)
{
    // Önce external ID ile ara
    var existingUser = await _context.Users
        .FirstOrDefaultAsync(u => u.OAuthProvider == provider && u.ExternalId == externalId);

    if (existingUser != null)
        return existingUser;

    // Email ile ara (provider farklı olsa bile aynı email varsa)
    existingUser = await _context.Users
        .FirstOrDefaultAsync(u => u.Email == email);

    if (existingUser != null)
    {
        // Mevcut kullanıcıya OAuth bilgisi ekle
        existingUser.OAuthProvider = provider;
        existingUser.ExternalId = externalId;
        await _context.SaveChangesAsync();
        return existingUser;
    }

    // Yeni kullanıcı oluştur
    var newUser = new User
    {
        Email = email,
        Username = email,
        FirstName = firstName,
        LastName = lastName,
        OAuthProvider = provider,
        ExternalId = externalId,
        PasswordHash = "",  // OAuth kullanıcıları için şifre yok
        Role = UserRole.Evaluator,  // Default rol
        IsActive = true
    };

    await _context.Users.AddAsync(newUser);
    await _context.SaveChangesAsync();

    return newUser;
}
